import 'dart:io';
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:image_picker/image_picker.dart';

import '../../core/providers.dart';
import '../../core/storage.dart';
import '../../core/theme.dart';
import '../../core/widgets.dart';

/// Photo step. Spec 1.4: minimum 3 photos required to continue.
class PhotosScreen extends ConsumerStatefulWidget {
  const PhotosScreen({super.key, required this.onNext});

  final VoidCallback onNext;

  @override
  ConsumerState<PhotosScreen> createState() => _PhotosScreenState();
}

class _PhotosScreenState extends ConsumerState<PhotosScreen> with FormProgress {
  Future<void> _add({required bool primary}) async {
    final picked = await ImagePicker().pickImage(
      source: ImageSource.gallery,
      maxWidth: 1600,
      maxHeight: 1600,
      imageQuality: 85,
    );
    if (picked == null) return;

    // Client-side resolution check
    final bytes = await File(picked.path).readAsBytes();
    final codec = await ui.instantiateImageCodec(bytes);
    final frame = await codec.getNextFrame();
    final width = frame.image.width;
    final height = frame.image.height;

    if (width < 480 || height < 480) {
      if (mounted) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          showDialog(
            context: context,
            builder: (_) => AlertDialog(
              backgroundColor: Tokens.tanCard,
              title: Text('Something went wrong', style: TextStyle(color: Tokens.pinkDeep)),
              content: Text('Please provide a larger photo', style: TextStyle(color: Tokens.pinkDeep)),
              actions: [
                TextButton(onPressed: () => Navigator.pop(context), child: const Text('OK', style: TextStyle(color: Tokens.pink))),
              ],
            ),
          );
        });
      }
      return;
    }

    await progress(() async {
      final profile = ref.read(myProfileProvider).valueOrNull;
      final url = await Storage.upload(
        Storage.pathFor(profile?.userId ?? 'unknown', 'profiles'),
        File(picked.path),
      );
      await ref.read(myProfileProvider.notifier).addPhoto(url, makePrimary: primary);
      // The server re-opens verification when the primary photo changes, so the
      // caller must re-check status rather than assume the old verdict stands.
      ref.invalidate(verificationProvider);
    });
  }

  @override
  Widget build(BuildContext context) {
    final profile = ref.watch(myProfileProvider);
    final gender = profile.valueOrNull?.gender ?? '';

    return Scaffold(
      appBar: AppBar(title: const Text('Add your profile photos')),
      body: AsyncView(
        value: profile,
        onRetry: () => ref.invalidate(myProfileProvider),
        builder: (data) {
          final photos = data.photos;
          final ready = photos.length >= 3;

          return ListView(
            padding: const EdgeInsets.all(Tokens.spaceMd),
            children: [
              Text(
                'You need to upload at least 3 photos to continue completing your profile. You can change them later',
                style: TextStyle(color: Colors.brown.shade500),
              ),
              const SizedBox(height: Tokens.spaceMd),

              GridView.count(
                crossAxisCount: 3,
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                mainAxisSpacing: Tokens.spaceSm,
                crossAxisSpacing: Tokens.spaceSm,
                children: [
                  for (var i = 0; i < photos.length; i++)
                    _PhotoTile(
                      url: photos[i],
                      isPrimary: i == 0,
                      label: i == 0 ? 'Primary photo' : 'Photo ${i + 1}',
                      gender: i == 0 ? gender : null,
                    ),
                  if (photos.length < 6)
                    _AddTile(
                      busy: busy,
                      label: photos.isEmpty ? 'Add photo' : 'Add another',
                      onTap: () => _add(primary: photos.isEmpty),
                    ),
                ],
              ),

              const SizedBox(height: Tokens.spaceLg),
              if (error != null) ...[
                ErrorText(error!),
                const SizedBox(height: Tokens.spaceMd),
              ],

              FilledButton(
                onPressed: ready && !busy ? widget.onNext : null,
                style: FilledButton.styleFrom(
                  minimumSize: const Size.fromHeight(52),
                  backgroundColor: Tokens.pink,
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(Tokens.radiusMd)),
                ),
                child: const Text('Add photos', style: TextStyle(fontWeight: FontWeight.w700, fontSize: 15)),
              ),
              const SizedBox(height: Tokens.spaceLg),
            ],
          );
        },
      ),
    );
  }
}

class _PhotoTile extends StatelessWidget {
  const _PhotoTile({
    required this.url,
    required this.isPrimary,
    required this.label,
    this.gender,
  });

  final String url;
  final bool isPrimary;
  final String label;
  final String? gender;

  @override
  Widget build(BuildContext context) => Stack(
        fit: StackFit.expand,
        children: [
          ClipRRect(
            borderRadius: const BorderRadius.all(Radius.circular(Tokens.radiusSm)),
            child: ProfilePhoto(url: url, label: label),
          ),
          if (isPrimary && gender != null)
            Positioned(
              bottom: Tokens.spaceXs,
              right: Tokens.spaceXs,
              child: Chip(
                label: Text(
                  gender!,
                  style: const TextStyle(color: Colors.white, fontSize: 10),
                ),
                backgroundColor: Tokens.pink,
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
              ),
            ),
        ],
      );
}

class _AddTile extends StatelessWidget {
  const _AddTile({required this.busy, required this.label, required this.onTap});

  final bool busy;
  final String label;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) => Semantics(
        button: true,
        label: label,
        child: InkWell(
          onTap: busy ? null : onTap,
          borderRadius: const BorderRadius.all(Radius.circular(Tokens.radiusSm)),
          child: DecoratedBox(
            decoration: BoxDecoration(
              borderRadius: const BorderRadius.all(Radius.circular(Tokens.radiusSm)),
              border: Border.all(color: Theme.of(context).colorScheme.outlineVariant),
            ),
            child: Center(
              child: busy
                  ? const SizedBox.square(dimension: 20, child: CircularProgressIndicator(strokeWidth: 2))
                  : const Icon(Icons.add_a_photo_outlined),
            ),
          ),
        ),
      );
}

import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter/rendering.dart';
import 'package:flutter/scheduler.dart';

import '../constants/app_constants.dart';
import '../theme/tokens.dart';

/// Performance and Live Preview HUD overlay.
/// Only active in debug/profile mode; in release mode it renders `child` with 0 overhead.
class DevPreviewOverlay extends StatefulWidget {
  const DevPreviewOverlay({
    super.key,
    required this.child,
    this.onToggleTheme,
    this.isDarkMode = false,
  });

  final Widget child;
  final VoidCallback? onToggleTheme;
  final bool isDarkMode;

  @override
  State<DevPreviewOverlay> createState() => _DevPreviewOverlayState();
}

enum DeviceSimulation {
  responsive('Fluid Desktop', null),
  mobile('Mobile (390x844)', Size(390, 844)),
  tablet('Tablet (820x1180)', Size(820, 1180));

  const DeviceSimulation(this.label, this.size);
  final String label;
  final Size? size;
}

class _DevPreviewOverlayState extends State<DevPreviewOverlay> {
  bool _showHud = true;
  bool _debugPaint = false;
  bool _repaintRainbow = false;
  DeviceSimulation _device = DeviceSimulation.responsive;

  // Real-time FPS & Frame timing metrics
  double _currentFps = 60.0;
  double _lastFrameMs = 16.0;
  int _droppedFrames = 0;
  final List<double> _frameHistory = [];

  void _onFrameTiming(List<FrameTiming> timings) {
    if (!mounted) return;
    for (final timing in timings) {
      final buildDurationMs = timing.buildDuration.inMicroseconds / 1000.0;
      final rasterDurationMs = timing.rasterDuration.inMicroseconds / 1000.0;
      final totalFrameMs = buildDurationMs + rasterDurationMs;

      _frameHistory.add(totalFrameMs);
      if (_frameHistory.length > 60) {
        _frameHistory.removeAt(0);
      }

      if (totalFrameMs > AppConstants.jankWarningThreshold) {
        _droppedFrames++;
      }

      final avgMs = _frameHistory.reduce((a, b) => a + b) / _frameHistory.length;
      final fps = (1000.0 / (avgMs > 0 ? avgMs : 16.666)).clamp(1.0, 120.0);

      setState(() {
        _lastFrameMs = totalFrameMs;
        _currentFps = fps;
      });
    }
  }

  @override
  void initState() {
    super.initState();
    if (kDebugMode) {
      SchedulerBinding.instance.addTimingsCallback(_onFrameTiming);
    }
  }

  @override
  void dispose() {
    if (kDebugMode) {
      SchedulerBinding.instance.removeTimingsCallback(_onFrameTiming);
    }
    super.dispose();
  }

  void _toggleLayoutBounds() {
    setState(() {
      _debugPaint = !_debugPaint;
      debugPaintSizeEnabled = _debugPaint;
    });
  }

  void _toggleRepaintRainbow() {
    setState(() {
      _repaintRainbow = !_repaintRainbow;
      debugRepaintRainbowEnabled = _repaintRainbow;
    });
  }

  @override
  Widget build(BuildContext context) {
    if (!kDebugMode) {
      return widget.child;
    }

    final simulatedSize = _device.size;
    final content = simulatedSize == null
        ? widget.child
        : Center(
            child: Container(
              width: simulatedSize.width,
              height: simulatedSize.height,
              clipBehavior: Clip.antiAlias,
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(Tokens.radiusLg),
                border: Border.all(color: Colors.white24, width: 3),
                boxShadow: Tokens.shadowLevel3,
              ),
              child: widget.child,
            ),
          );

    return Material(
      type: MaterialType.transparency,
      child: Stack(
        fit: StackFit.expand,
        children: [
          content,
          if (_showHud) _buildFloatingDevHud(context),
          _buildHudToggleChip(),
        ],
      ),
    );
  }

  Widget _buildHudToggleChip() {
    return Positioned(
      top: 36,
      right: 16,
      child: Material(
        color: Colors.transparent,
        child: InkWell(
          onTap: () => setState(() => _showHud = !_showHud),
          borderRadius: BorderRadius.circular(Tokens.radiusPill),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
            decoration: BoxDecoration(
              color: Colors.black.withValues(alpha: 0.8),
              borderRadius: BorderRadius.circular(Tokens.radiusPill),
              border: Border.all(color: Colors.white24),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                _buildFpsDot(),
                const SizedBox(width: 6),
                Text(
                  '${_currentFps.toStringAsFixed(0)} FPS',
                  style: TextStyle(
                    color: _getFpsColor(),
                    fontSize: 12,
                    fontWeight: FontWeight.bold,
                    fontFamily: 'monospace',
                  ),
                ),
                const SizedBox(width: 4),
                Icon(
                  _showHud ? Icons.expand_less : Icons.tune,
                  color: Colors.white70,
                  size: 16,
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildFpsDot() {
    return Container(
      width: 8,
      height: 8,
      decoration: BoxDecoration(
        color: _getFpsColor(),
        shape: BoxShape.circle,
      ),
    );
  }

  Color _getFpsColor() {
    if (_currentFps >= 55) return const Color(0xFF00E676);
    if (_currentFps >= 40) return const Color(0xFFFFB300);
    return const Color(0xFFFF5252);
  }

  Widget _buildFloatingDevHud(BuildContext context) {
    return Positioned(
      top: 80,
      right: 16,
      child: Container(
        width: 260,
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: const Color(0xEE181824),
          borderRadius: BorderRadius.circular(Tokens.radiusMd),
          border: Border.all(color: Colors.white12),
          boxShadow: Tokens.shadowLevel2,
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              children: [
                const Icon(Icons.bolt, color: Color(0xFF8E2DE2), size: 16),
                const SizedBox(width: 6),
                const Expanded(
                  child: Text(
                    'DEV INSPECTOR HUD',
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 11,
                      fontWeight: FontWeight.w700,
                      letterSpacing: 1.0,
                    ),
                  ),
                ),
                Text(
                  '${_lastFrameMs.toStringAsFixed(1)}ms',
                  style: const TextStyle(
                    color: Colors.white54,
                    fontSize: 11,
                    fontFamily: 'monospace',
                  ),
                ),
              ],
            ),
            const Divider(color: Colors.white10, height: 16),
            _buildHudAction(
              icon: Icons.border_all,
              label: 'Layout Bounds',
              active: _debugPaint,
              onTap: _toggleLayoutBounds,
            ),
            const SizedBox(height: 6),
            _buildHudAction(
              icon: Icons.color_lens_outlined,
              label: 'Repaint Rainbow',
              active: _repaintRainbow,
              onTap: _toggleRepaintRainbow,
            ),
            const SizedBox(height: 6),
            if (widget.onToggleTheme != null) ...[
              _buildHudAction(
                icon: widget.isDarkMode ? Icons.dark_mode : Icons.light_mode,
                label: widget.isDarkMode ? 'Theme: Dark' : 'Theme: Light',
                active: widget.isDarkMode,
                onTap: widget.onToggleTheme!,
              ),
              const SizedBox(height: 6),
            ],
            const SizedBox(height: 4),
            const Text(
              'VIEWPORT SIMULATION',
              style: TextStyle(
                color: Colors.white38,
                fontSize: 9,
                fontWeight: FontWeight.w600,
                letterSpacing: 0.5,
              ),
            ),
            const SizedBox(height: 6),
            Wrap(
              spacing: 6,
              runSpacing: 4,
              children: DeviceSimulation.values.map((dev) {
                final isSelected = _device == dev;
                return ChoiceChip(
